const kinds = ['maintenance', 'purchase'];
const statusKeys = ['received', 'reviewing', 'linked_order', 'approved', 'closed'];
const items = $input.all();
const rows = items.length === 1 ? items[0].json.requests : null;
const fail = () => { throw new Error('Formato do resumo de solicitações inesperado. Confira o contrato da API.'); };
const count = value => Number.isSafeInteger(value) && value >= 0 ? value : fail();
if (!Array.isArray(rows) || rows.length !== kinds.length) fail();

return kinds.map(kind => {
  const matches = rows.filter(row => row?.kind === kind);
  if (matches.length !== 1) fail();
  const row = matches[0];
  const statuses = Object.fromEntries(statusKeys.map(status => [status, count(row.statuses?.[status])]));
  const total = count(row.total);
  const due_today = count(row.due_today);
  const past_due = count(row.past_due);
  if (Object.values(statuses).reduce((sum, value) => sum + value, 0) !== total || due_today + past_due > total) fail();
  return { json: { kind, total, statuses, due_today, past_due } };
});
